  addSection("top100", `<p class="eyebrow">Direct chart pass-through</p><h2>Nigeria Top 100 Songs</h2><p class="supplement-intro">Weekly chart snapshot from <a href="https://www.turntablecharts.com/charts/1" target="_blank" rel="noopener noreferrer">TurnTable Charts</a>. This table is not scored by Afri Index; it preserves the chart’s own rank, movement and metadata.</p><p class="source-tag">Chart dated 10 Sep 2026 · checked 21 Sep 2026 · 100 entries · TurnTable Charts ↗</p><table class="top100-table"><thead><tr><th>Rank</th><th>Title</th><th>Artist</th><th>Last week</th><th>Weeks</th><th>Peak</th><th>Status</th></tr></thead><tbody>${top100.map(r=>{const movement=r[6] || (r[3]===r[0]?"—":r[3]>r[0]?`↑ ${r[3]-r[0]}`:`↓ ${r[0]-r[3]}`);const movementClass=movement.startsWith("↑")?"movement-up":movement.startsWith("↓")?"movement-down":"movement-flat";return `<tr><td>${r[0]}</td><td>${esc(r[1])}</td><td>${esc(r[2])}</td><td>${r[3]||"—"}</td><td>${r[4]}</td><td>${r[5]}</td><td class="${movementClass}">${esc(movement)}</td></tr>`}).join("")}</tbody></table><p class="archive-note">The latest TurnTable chart available when checked on 21 Sep 2026 covers 4–10 Sep 2026</p>`);
  addSection("news", `<p class="eyebrow">Sourced editorial notes</p><h2>Artist News</h2><p class="supplement-intro">Short, reverse-chronological updates. Every item links to a checkable source or an Afri Index audit page; this is manually curated alongside the data refresh.</p><div class="news-list">${news.map(n=>`<article class="news-item"><h3>${esc(n.headline)}</h3><p>${esc(n.summary)}</p><small>${esc(n.date)} · ${esc(n.artist)} · <a href="${esc(n.url)}">${esc(n.source)} ↗</a></small></article>`).join("")}</div>`);
