  if (method && !method.querySelector(".master-method-notes")) {
    const notes = document.createElement("div"); notes.className="master-method-notes yearly-method mt-8";
    notes.innerHTML = `<h3 class="font-semibold text-lg mb-2">Source and scoring notes</h3><p class="text-sm text-gray-700"><strong>Awards:</strong> Wikipedia’s English artist page or dedicated awards list is the coverage guide, not the final authority. Published totals and award-body breakdowns are retained; only individually highlighted results with a direct non-Wikipedia source appear as verified highlights. Profiles without a structured published total keep an explicit audited coverage state.</p><p class="text-sm text-gray-700 mt-3"><strong>Streams:</strong> Spotify/Kworb is the primary catalogue source. The 21 Sep pass refreshed 50 of 50 catalogue totals, daily rates, tracked-song rows and album ledgers; Music Metrics Vault returned 49 valid monthly-listener values. Failed fields retained their previous verified values. YouTube, Audiomack and Boomplay remain nullable last-good signals when no comparable ledger returns.</p><p class="text-sm text-gray-700 mt-3"><strong>Calendar year:</strong> active-year album and song rows keep explicit year and release-date fields, use the meaningful-activity rule and rank strictly by streams_this_year. Prior years remain archived; their displayed catalogue references are not relabelled as historical calendar-year totals.</p><p class="text-sm text-gray-700 mt-3"><strong>Certifications:</strong> TurnTable Charts’ Nigerian ledger is the local reference; international plaques link to RIAA, BPI, Music Canada or SNEP. Failed register pages retain prior matches and every unmatched artist receives a dated no-match audit state.</p><p class="text-sm text-gray-700 mt-3"><strong>Top 100:</strong> the weekly Nigeria chart is a dated TurnTable pass-through, not an Afri Index score. <strong>Underground:</strong> entries remain unranked and contain no invented biography details. <strong>News:</strong> every item now links to a checkable public source.</p>`;
    method.append(notes);
  }
